                    Sum(
                        StockRows,
                        quantity
                    )
                )
            );

            // ======================================
            // 4A. LOCAL STOCK UPDATE
            // ======================================

            ForAll(
                colStockDelta As d,

                With(
                    {
                        existingStock:
                            LookUp(
                                colOfflineStock,
                                itemNo = d.itemNo &&
                                locationCode = d.locationCode
                            )
                    },

                    If(
                        IsBlank(existingStock),

                        Collect(
                            colOfflineStock,
                            {
                                itemNo: d.itemNo,
                                locationCode: d.locationCode,
                                quantity: d.DeltaQty
                            }
                        ),

                        Patch(
                            colOfflineStock,
                            existingStock,
                            {
                                quantity:
                                    existingStock.quantity +
                                    d.DeltaQty
                            }
                        )
                    )
                )
            );

            // ======================================
            // 4B. BC CHECK SNAPSHOT UPDATE
            // ======================================

            ForAll(
                colStockDelta As d,

                With(
                    {
                        existingCheck:
                            LookUp(
                                colBCStockCheck,
                                itemNo = d.itemNo &&
                                locationCode = d.locationCode
                            )
                    },

                    If(
                        IsBlank(existingCheck),

                        Collect(
                            colBCStockCheck,
                            {
                                itemNo: d.itemNo,
                                locationCode: d.locationCode,
                                quantity: d.DeltaQty
                            }
                        ),

                        Patch(
                            colBCStockCheck,
                            existingCheck,
                            {
                                quantity:
                                    existingCheck.quantity +
                                    d.DeltaQty
                            }
                        )
                    )
                )
            );

            // ======================================
            // LAST ENTRY UPDATE
            // ======================================

            ClearCollect(
                colStockSyncInfo,
                {
                    LastEntryNo:
                        Max(
                            colStockEntries,
                            entryNo
                        )
                }
            );

            // ======================================
            // SAVE LOCAL
            // ======================================

            SaveData(
                colOfflineStock,
                "OfflineStock"
            );

            SaveData(
                colBCStockCheck,
                "BCStockCheck"
            );

            SaveData(
                colStockSyncInfo,
                "StockSyncInfo"
            )
        );

        // ==========================================
        // 5. LAST BATCH
        // ==========================================

        If(
            CountRows(colStockEntries) < 1000,

            Set(
                varStockAutoSync,
                false
            );

